def choose_move(observation):
    def sign(v):
        return 1 if v > 0 else (-1 if v < 0 else 0)

    def pos(value, default=(0, 0)):
        if isinstance(value, (list, tuple)) and len(value) >= 2:
            return value[0], value[1]
        return default

    def nearest(items, sx, sy):
        best = None
        best_d = None
        for item in items or []:
            x, y = pos(item, None)
            if x is None:
                continue
            d = abs(x - sx) + abs(y - sy)
            if best_d is None or d < best_d:
                best_d = d
                best = (x, y)
        return best

    env = observation.get("environment_name", "resource_collection")
    sx, sy = pos(observation.get("self_position"))
    ox, oy = pos(observation.get("opponent_position"), (sx, sy))
    gw = observation.get("grid_width", 0)
    gh = observation.get("grid_height", 0)

    if env == "pursuit_evasion":
        role = observation.get("self_role", "pursuer")
        if role == "pursuer":
            return [sign(ox - sx), sign(oy - sy)]
        corners = [(0, 0), (0, max(0, gh - 1)), (max(0, gw - 1), 0), (max(0, gw - 1), max(0, gh - 1))]
        target = max(corners, key=lambda c: abs(c[0] - ox) + abs(c[1] - oy))
        return [sign(target[0] - sx), sign(target[1] - sy)]

    if env == "territory_control":
        targets = observation.get("unclaimed_cells") or observation.get("opponent_territory") or observation.get("frontier") or []
        target = nearest(targets, sx, sy)
        if target is None:
            return [sign(ox - sx), sign(oy - sy)] if (ox, oy) != (sx, sy) else [0, 0]
        return [sign(target[0] - sx), sign(target[1] - sy)]

    resources = observation.get("resources") or observation.get("resource_cells") or observation.get("resource_positions") or []
    target = nearest(resources, sx, sy)
    if target is not None:
        return [sign(target[0] - sx), sign(target[1] - sy)]

    # Fallback: resource denial / opponent pressure / exploration
    if (ox, oy) != (sx, sy):
        return [sign(ox - sx), sign(oy - sy)]

    # Mild exploration based on any available biases.
    turn = observation.get("turn", 0)
    if turn % 2 == 0:
        return [1, 0]
    return [0, 1]

